// Inline-SVG rice-plant accumulation map -- a line-for-line port of src/plot_svg.py.
//
// Ported (rather than fetched from the server per frame) so the day slider scrubs
// the whole season in the browser with no round trip. The output string is
// byte-identical to the Python one; src/__tests__/plantSvg.test.ts pins that
// against fixtures generated by plot_svg.plant_svg.

import { fmtF, fmtG, roundHalfEven } from "./format";
import type { Lang, RunResult, Tissue } from "./types";

const STOPS: [number, [number, number, number]][] = [
  [0.0, [244, 247, 238]], [0.22, [234, 223, 155]], [0.5, [231, 178, 76]],
  [0.75, [217, 138, 68]], [1.0, [180, 86, 46]],
];
export const SKY = "#8FCFEE";
const SOIL = "#B98A4E";
const SOIL_DK = "#95672F";
const SPECK = "#6F4A24";
const INK = "#211E18";
const MUTED = "#5C554A";
const BORDER = "#E4DCCE";
const LEADER = "#C9B48C";
const PWBG = "#4A3520";
const PWTX = "#F3EAD4";
const CHIP_TOP: [string, string] = ["#FBE4DE", "#B23A2E"];
const FONT = "'Malgun Gothic','맑은 고딕',sans-serif";
const MONO = "'DM Mono','SFMono-Regular',Consolas,'Malgun Gothic',monospace";

const LAB: Record<Lang, Record<string, string>> = {
  ko: { root: "뿌리", stem: "줄기", leaf: "잎", grain: "낟알", conc: "농도", high: "높음",
        low: "낮음", pw: "공극수", top: "최고", safe: "안전", warn: "주의", dang: "초과" },
  en: { root: "Roots", stem: "Stem", leaf: "Leaf", grain: "Grain", conc: "level", high: "high",
        low: "low", pw: "pore water", top: "top", safe: "safe", warn: "caution", dang: "over" },
};
const SIGCHIP: Record<string, [string, string, string]> = {
  green: ["safe", "#DCEFE6", "#0E6B4F"],
  amber: ["warn", "#FAEBD1", "#9A5A00"],
  red: ["dang", "#FADEDA", "#B23A2E"],
};

const fin = (v: number | null | undefined): v is number =>
  v !== null && v !== undefined && Number.isFinite(v);

function heat(f: number): string {
  f = Math.max(0, Math.min(1, f));
  for (let i = 0; i < STOPS.length - 1; i++) {
    const [a, ca] = STOPS[i];
    const [b, cb] = STOPS[i + 1];
    if (f <= b) {
      const t = b === a ? 0 : (f - a) / (b - a);
      const r = [0, 1, 2].map((k) => roundHalfEven(ca[k] + (cb[k] - ca[k]) * t));
      return `rgb(${r[0]},${r[1]},${r[2]})`;
    }
  }
  return "rgb(180,86,46)";
}

function frac(v: number | null | undefined, cmin: number, cmax: number): number | null {
  if (!fin(v)) return null;
  return cmax <= cmin ? 0.5 : Math.min(1, Math.max(0, (v - cmin) / (cmax - cmin)));
}

function col(v: number | null | undefined, cmin: number, cmax: number): string {
  const f = frac(v, cmin, cmax);
  return f === null ? "#dcdcdc" : heat(f);
}

const fmt = (v: number | null | undefined) => (fin(v) ? fmtG(v, 3) : "—");

const leader = (x1: number, y1: number, x2: number, y2: number) =>
  `<path d="M${x1},${y1} L${x2},${y2}" fill="none" stroke="${LEADER}" stroke-width="1.4"/>`;

function card(x: number, y: number, name: string, val: string, swatch: string,
              chip: [string, string, string] | null, unit: string): string {
  const w = 168, h = 48;
  const out = [
    `<g><rect x="${x}" y="${y}" width="${w}" height="${h}" rx="12" fill="#FFFFFF" ` +
      `stroke="${BORDER}" stroke-width="1"/>`,
    `<rect x="${x + 10}" y="${y + 11}" width="7" height="${h - 22}" rx="3.5" fill="${swatch}"/>`,
    `<text x="${x + 26}" y="${y + 20}" font-size="13" font-weight="700" fill="${INK}" ` +
      `font-family="${FONT}">${name}</text>`,
    `<text x="${x + 26}" y="${y + 38}" font-family="${MONO}">` +
      `<tspan font-size="14" fill="${MUTED}">${val}</tspan>` +
      (unit ? `<tspan font-size="10.5" fill="${MUTED}" dx="4" font-family="${FONT}">${unit}</tspan>` : "") +
      "</text>",
  ];
  if (chip) {
    const [label, cbg, ctx] = chip;
    const cw = 34 + 8 * Math.max(0, label.length - 2);
    out.push(`<rect x="${x + w - cw - 10}" y="${y + 9}" width="${cw}" height="18" rx="9" fill="${cbg}"/>`);
    out.push(`<text x="${fmtF(x + w - 10 - cw / 2, 0)}" y="${y + 22}" font-size="11" font-weight="700" ` +
             `fill="${ctx}" text-anchor="middle" font-family="${FONT}">${label}</text>`);
  }
  out.push("</g>");
  return out.join("");
}

export interface PlantValues { root?: number | null; stem?: number | null; leaf?: number | null;
                               grain?: number | null; straw?: number | null }

export function plantSvg(values: PlantValues, opts: {
  cmin: number; cmax: number; cwo?: number | null; lang?: Lang; labels?: boolean;
  grainSignal?: string | null; bg?: string; W?: number; H?: number; unit?: string;
}): string {
  const { cmin, cmax, cwo = null, lang = "ko", labels = true, grainSignal = null, bg = SKY,
          W = 760, H = 560, unit = "µg/kg" } = opts;
  const L = LAB[lang] ?? LAB.ko;
  const root = values.root;
  const stem = values.stem !== undefined ? values.stem : values.straw;
  const leaf = values.leaf !== undefined ? values.leaf : values.straw;
  const grain = values.grain;
  const cr = col(root, cmin, cmax), cs = col(stem, cmin, cmax);
  const cl = col(leaf, cmin, cmax), cg = col(grain, cmin, cmax);
  const named: Record<string, number | null | undefined> = { root, stem, leaf, grain };
  let topOrgan: string | null = null;
  let best = -Infinity;
  for (const k of ["root", "stem", "leaf", "grain"]) {   // Python max(): first max wins
    const v = named[k];
    if (fin(v) && v > best) { best = v; topOrgan = k; }
  }

  const tx = 120, ty = 70, soilTop = 476;
  const P: string[] = [];
  P.push(`<rect x="0" y="0" width="${W}" height="${H}" rx="20" fill="${bg}"/>`);
  P.push(`<path d="M0,${soilTop} Q190,${soilTop - 8} 380,${soilTop - 2} ` +
         `Q560,${soilTop + 4} ${W},${soilTop - 6} L${W},${H} L0,${H} Z" fill="${SOIL}"/>`);
  P.push(`<path d="M0,${soilTop + 34} Q220,${soilTop + 26} 430,${soilTop + 32} ` +
         `Q600,${soilTop + 38} ${W},${soilTop + 30} L${W},${H} L0,${H} Z" fill="${SOIL_DK}" opacity="0.6"/>`);
  for (const [sx, sy, r] of [[150, 520, 3], [240, 536, 2.4], [470, 520, 3], [610, 540, 2.4], [330, 545, 2.4]]) {
    P.push(`<ellipse cx="${sx}" cy="${sy}" rx="${r}" ry="${fmtF(r * 0.7, 1)}" fill="${SPECK}" opacity="0.5"/>`);
  }

  P.push(`<g transform="translate(${tx},${ty})">`);
  P.push(`<g stroke="${cr}" stroke-width="18" stroke-linecap="round" fill="none">` +
         `<path d="M246,394 A42,42 0 0 1 198.9,435.7"/>` +
         `<path d="M266,394 A42,42 0 0 0 313.1,435.7"/>` +
         `<path d="M256,395 L256,452"/></g>`);
  P.push(`<circle cx="256" cy="378" r="24" fill="${bg}"/>`);
  P.push(`<g stroke="${cs}" stroke-width="30" stroke-linecap="round" fill="none">` +
         `<path d="M256,378 L256,170 A80,80 0 0 1 296,100.7"/></g>`);
  P.push(`<g stroke="${cl}" stroke-width="30" stroke-linecap="round" fill="none">` +
         `<path d="M178.1,172.6 L216.9,211.4"/><path d="M333.3,215.5 L294.5,254.3"/>` +
         `<path d="M178.3,258.2 L217.1,297.0"/><path d="M333.3,296.7 L294.5,335.5"/></g>`);
  P.push(`<g fill="${cg}">` +
         `<ellipse cx="349.3" cy="63.5" rx="28.8" ry="18.7" transform="rotate(-22 349.3 63.5)"/>` +
         `<ellipse cx="398.7" cy="101.3" rx="28.8" ry="18.7" transform="rotate(27 398.7 101.3)"/>` +
         `<ellipse cx="352.3" cy="123.1" rx="28.8" ry="18.7" transform="rotate(52 352.3 123.1)"/>` +
         `<ellipse cx="409.9" cy="157.3" rx="28.8" ry="18.7" transform="rotate(51 409.9 157.3)"/></g>`);
  P.push("</g>");

  if (labels) {
    const ends: Record<string, [number, number]> = { grain: [472, 190], leaf: [298, 328],
                                                     stem: [376, 356], root: [376, 498] };
    const starts: Record<string, [number, number]> = { grain: [198, 174], leaf: [198, 306],
                                                       stem: [198, 388], root: [198, 500] };
    for (const k of ["grain", "leaf", "stem", "root"]) {
      const [sx, sy] = starts[k];
      const [ex, ey] = ends[k];
      P.push(leader(sx, sy, ex, ey));
      P.push(`<circle cx="${ex}" cy="${ey}" r="3" fill="${LEADER}"/>`);
    }
    const chipFor = (key: string): [string, string, string] | null => {
      if (key === topOrgan) return [L.top, CHIP_TOP[0], CHIP_TOP[1]];
      if (key === "grain" && grainSignal && grainSignal in SIGCHIP) {
        const [nm, cbg, ctx] = SIGCHIP[grainSignal];
        return [L[nm], cbg, ctx];
      }
      return null;
    };
    P.push(card(30, 150, L.grain, fmt(grain), cg, chipFor("grain"), unit));
    P.push(card(30, 282, L.leaf, fmt(leaf), cl, chipFor("leaf"), unit));
    P.push(card(30, 364, L.stem, fmt(stem), cs, chipFor("stem"), unit));
    P.push(card(30, 476, L.root, fmt(root), cr, chipFor("root"), unit));
  }

  if (fin(cwo)) {
    P.push(`<g><rect x="${W - 232}" y="${H - 70}" width="196" height="42" rx="14" fill="${PWBG}"/>` +
           `<text x="${W - 134}" y="${H - 52}" text-anchor="middle" font-size="12.5" ` +
           `font-weight="700" fill="${PWTX}" font-family="${FONT}">${L.pw}</text>` +
           `<text x="${W - 134}" y="${H - 36}" text-anchor="middle" font-size="12" ` +
           `fill="${PWTX}" font-family="${MONO}">PFAS = ${fmtG(cwo, 3)} µg/L</text></g>`);
  }

  const lg = STOPS.map(([p, c]) => `<stop offset="${fmtF(p * 100, 0)}%" stop-color="rgb(${c.join(", ")})"/>`).join("");
  const gx = W - 48;
  P.push(`<defs><linearGradient id="pfaslg" x1="0" y1="1" x2="0" y2="0">${lg}</linearGradient></defs>`);
  P.push(`<rect x="${W - 98}" y="160" width="82" height="282" rx="16" fill="#FFFFFF" ` +
         `stroke="${BORDER}" stroke-width="1"/>`);
  P.push(`<text x="${gx + 7}" y="186" font-size="12" fill="${MUTED}" text-anchor="middle" ` +
         `font-family="${FONT}">${L.conc}</text>`);
  P.push(`<rect x="${gx}" y="206" width="14" height="200" rx="7" fill="url(#pfaslg)"/>`);
  P.push(`<text x="${gx - 9}" y="212" font-size="11" fill="${MUTED}" text-anchor="end" ` +
         `font-family="${FONT}">${L.high}</text>`);
  P.push(`<text x="${gx - 9}" y="406" font-size="11" fill="${MUTED}" text-anchor="end" ` +
         `font-family="${FONT}">${L.low}</text>`);

  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${W} ${H}" ` +
    `preserveAspectRatio="xMidYMid meet" font-family="${FONT}" ` +
    `style="width:100%;height:auto;display:block">` +
    `<defs><clipPath id="pfascard"><rect x="0" y="0" width="${W}" height="${H}" rx="24"/></clipPath></defs>` +
    `<g clip-path="url(#pfascard)">` + P.join("") + "</g></svg>";
}

/** `plot_svg.plant_svg_from_res` on the run payload (model_api.schematic_values). */
export function plantSvgFromRun(r: RunResult, tIndex: number, opts: {
  lang?: Lang; metric?: "conc" | "baf"; grainSignal?: string | null;
} = {}): string {
  const metric = opts.metric ?? "conc";
  const n = r.t.length;
  const ti = tIndex < 0 ? n + tIndex : tIndex;
  const data = metric === "baf" ? r.baf : r.conc;
  const values: PlantValues = {};
  for (const k of ["root", "stem", "leaf", "grain"] as Tissue[]) values[k] = data[k][ti];
  const s = r.schematic[metric];
  return plantSvg(values, { cmin: s.cmin, cmax: s.cmax, cwo: r.Cwo[ti], lang: opts.lang ?? "ko",
                            grainSignal: opts.grainSignal ?? null,
                            unit: metric === "baf" ? "L/kg" : "µg/kg" });
}

export function nearestIndex(t: number[], day: number): number {
  let best = 0, bd = Infinity;
  for (let i = 0; i < t.length; i++) {
    const d = Math.abs(t[i] - day);
    if (d < bd) { bd = d; best = i; }
  }
  return best;
}
